// Retire editable quantities on a new copy; retain coupled fixed mounting rows.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Runtime.InteropServices;using System.Text.RegularExpressions;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{
static IZDoc D(object x){return x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));}
public static int Run(string folder){var j=new JavaScriptSerializer{MaxJsonLength=64000000};var r=new Dictionary<string,object>();try{
var request=(Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(request["expected_pid"]))throw new Exception("Host changed");dynamic l=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)l.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");string source=(string)request["source"],output=(string)request["output"],snapshot=(string)request["snapshot"];if(File.Exists(output)||File.Exists(snapshot))throw new Exception("Output/snapshot exists");var docs=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).ToArray();var original=docs.SingleOrDefault(d=>d.Name==source);
if(original!=null){bool changed=original.Modified;string guid=original.FileGUID;((IZSceneDoc)original).SaveAsCopy(snapshot,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);if(original.Name!=source||original.Modified!=changed||original.FileGUID!=guid)throw new Exception("Original state changed");}else File.Copy(source,snapshot,false);
foreach(var a in AppDomain.CurrentDomain.GetAssemblies()){var t=a.GetType("RockPro.CAD.MountCountController");if(t!=null)t.GetMethod("Stop").Invoke(null,null);}string working=Path.Combine(folder,"working.ics");File.Copy(snapshot,working,false);bool already;var doc=app.OpenFile2(working,false,true,out already);if(already)throw new Exception("Already open");var s=(IZSceneDoc)doc;var u=(IZSceneDocUtility)s;var props=s.GetTopElement().get_CustomPropMgr(false);var q=(Dictionary<string,object>)j.DeserializeObject((string)props.GetValueByName("RockPro.MountCounts.v1"));if((string)q["contract"]!="rockpro-tv-counts-v3"||((object[])q["rows"]).Length!=0)throw new Exception("Expected R005 portable manifest");
var frozen=new List<object>();foreach(var row in ((object[])q["portable_rows"]).Cast<Dictionary<string,object>>()){
var roots=(object[])row["roots"];int count=0;bool gap=false;foreach(var slot in roots){var states=((object[])slot).Select(id=>u.GetElementById(Convert.ToInt32(id)).GetStateStatus(eZElementState.Z_SUPPRESSED)).Distinct().ToArray();if(states.Length!=1)throw new Exception("Incomplete hardware pair");if(states[0])gap=true;else{if(gap)throw new Exception("Noncontiguous row");count++;}}
row["fixed_count"]=count;row.Remove("count");frozen.Add(new{key=row["key"],count=count});}
q["fixed_quantities"]=true;q["quantity_policy"]="Fixed existing hardware only. No parameter adds/removes instances.";props.SetValueByName("RockPro.MountCounts.v1",j.Serialize(q));
var mgr=s.ParameterMgr;var remove=Enumerable.Range(0,mgr.Count).Select(i=>mgr.GetParameter(i)).Where(p=>p.Name.EndsWith("_Liczba",StringComparison.Ordinal)).ToArray();var values=remove.ToDictionary(p=>p.Name,p=>p.Value.ToString("G16",System.Globalization.CultureInfo.InvariantCulture));
foreach(var p in Enumerable.Range(0,mgr.Count).Select(i=>mgr.GetParameter(i))){if(p.Type==eZParamType.Z_PARAMETER_TYPE_TEXT)continue;string expr=p.Expression;foreach(var pair in values)expr=Regex.Replace(expr,@"\b"+Regex.Escape(pair.Key)+@"\b","("+pair.Value+")");if(expr!=p.Expression)p.Expression=expr;}
foreach(string name in values.Keys.ToArray())mgr.DeleteParam((ZParameter)mgr.GetParameterByName(name));s.Update();var controller=Assembly.LoadFrom((string)request["controller"]).GetType("RockPro.CAD.MountCountController");controller.GetMethod("Apply").Invoke(null,new object[]{s});var status=mgr.GetParameterByName("RP_IloscOkuc_Status");status.TextParameterValue="OK — stały zestaw okuć; położenie i wycięcia są zsynchronizowane.";status.Notes="Kontrola położenia stałego zestawu okuć i ich wycięć. Liczba nie jest parametrem. BŁĄD: popraw położenie, rozstaw lub wymiary.";
s.SaveAs(output,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);app.ActiveDoc=doc;controller.GetMethod("Start").Invoke(null,new object[]{app});r["removed"]=values.Keys.ToArray();r["fixed_rows"]=frozen;r["parameters"]=mgr.Count;r["output"]=output;r["snapshot"]=snapshot;r["passed"]=true;
}catch(Exception ex){r["passed"]=false;r["error"]=ex.ToString();}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(r));return(bool)r["passed"]?0:1;}}}
